    [this, exp.Literal.string(path.name)]
),

TokenType.DCOLONDOLLAR: lambda self, this, path: build_json_extract_path(
    exp.JSONExtractScalar, json_type="STRING"
)([this, exp.Literal.string(path.name)]),

